    @card.toggle_assignment users(:kevin)
    @card.comments.destroy_all # To skip deduplication logic

    assert_system_comment "David unassigned from Kevin" do
      @card.toggle_assignment users(:kevin)
    end
  end

  test "card_closed" do
    assert_system_comment "Moved to “Done” by David" do
      @card.close
    end
  end

